const doc={comment:"/**\n   * ---\n   * category: utilities/layout\n   * ---\n   * Custom prop types for `ui-responsive` components.\n   * @module ResponsivePropTypes\n   */",meta:{filename:"n1fxknzjy2o43a65objygv.js",lineno:68,columnno:2,path:"/var/folders/0n/sx47w_6902sg9k_8_151tnqm0000gq/T",code:{}},description:"Custom prop types for `ui-responsive` components.",kind:"module",name:"ResponsivePropTypes",longname:"module:ResponsivePropTypes",sections:[{comment:"/**\n   * Verify that the given prop is a properly formatted query object\n   * with exactly one key and one corresponding valid value of type\n   * string or number. The object key should be one of `minWidth`,\n   * `maxWidth`, `minHeight`, or `maxHeight`. Note that key values\n   * should be camel cased.\n   *\n   *\n   * The following are examples of valid query objects:\n   *\n   * ```js\n   * { minWidth: 350 }\n   * { maxHeight: '400px' }\n   * { maxWidth: '20rem' }\n   * ```\n   *\n   * The following are examples of invalid query objects:\n   *\n   * ```js\n   * { minwidth: 300 } // should be minWidth (case sensitive)\n   * { minHeight: 200, maxHeight: 300 } // should consist of exactly one key\n   * ```\n   * @param {Object} props - object containing the component props\n   * @param {string} propName - name of the given prop\n   * @param {string} componentName - name of the component\n   * @returns {Error} if prop is an invalid query\n   */",meta:{range:[2186,2416],filename:"n1fxknzjy2o43a65objygv.js",lineno:55,columnno:2,path:"/var/folders/0n/sx47w_6902sg9k_8_151tnqm0000gq/T",code:{id:"astnode100000010",name:"validQuery",type:"FunctionExpression"}},description:"Verify that the given prop is a properly formatted query object\nwith exactly one key and one corresponding valid value of type\nstring or number. The object key should be one of `minWidth`,\n`maxWidth`, `minHeight`, or `maxHeight`. Note that key values\nshould be camel cased.\n\n\nThe following are examples of valid query objects:\n\n```js\n{ minWidth: 350 }\n{ maxHeight: '400px' }\n{ maxWidth: '20rem' }\n```\n\nThe following are examples of invalid query objects:\n\n```js\n{ minwidth: 300 } // should be minWidth (case sensitive)\n{ minHeight: 200, maxHeight: 300 } // should consist of exactly one key\n```",params:[{type:{names:["Object"]},description:"object containing the component props",name:"props"},{type:{names:["string"]},description:"name of the given prop",name:"propName"},{type:{names:["string"]},description:"name of the component",name:"componentName"}],returns:[{type:{names:["Error"]},description:"if prop is an invalid query"}],name:"validQuery",longname:"ResponsivePropTypes.validQuery",kind:"function",memberof:"ResponsivePropTypes",scope:"static",id:"ResponsivePropTypes.validQuery",title:"ResponsivePropTypes.validQuery"}],undocumented:!1,category:"utilities/layout",order:"",relativePath:"packages/ui-responsive/src/ResponsivePropTypes.js",extension:".js",srcPath:"packages/ui-responsive/src/ResponsivePropTypes.js",srcUrl:"https://github.com/instructure/instructure-ui/tree/master/packages/ui-responsive/src/ResponsivePropTypes.js",packageName:"@instructure/ui-responsive",requirePath:"@instructure/ui-responsive/lib/ResponsivePropTypes",requireStr:"require('/Users/balazs.saros/work/v7/instructure-ui/packages/ui-responsive/src/ResponsivePropTypes.js').default",esPath:"@instructure/ui-responsive/es/ResponsivePropTypes",id:"ResponsivePropTypes",title:"ResponsivePropTypes"}
